import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static String next() {
        while (buf[pos] <= ' ') pos++;
        int start = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        while (buf[pos] <= ' ') pos++;
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt(), k = nextInt();
        long[] a = new long[n], suffix = new long[n + 1];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        for (int i = n - 1; i >= 0; i--) suffix[i] = suffix[i + 1] | a[i];
        // spend every doubling on one element; try each element
        long prefix = 0, answer = 0;
        for (int i = 0; i < n; i++) {
            answer = Math.max(answer, prefix | (a[i] << k) | suffix[i + 1]);
            prefix |= a[i];
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<20)
	sc.Split(bufio.ScanWords)
	next := func() int {
		sc.Scan()
		v, _ := strconv.Atoi(sc.Text())
		return v
	}
	n, k := next(), next()
	a, suffix := make([]int, n), make([]int, n+1)
	for i := range a {
		a[i] = next()
	}
	for i := n - 1; i >= 0; i-- {
		suffix[i] = suffix[i+1] | a[i]
	}
	// spend every doubling on one element; try each element
	prefix, answer := 0, 0
	for i, v := range a {
		answer = max(answer, prefix|(v<<k)|suffix[i+1])
		prefix |= v
	}
	fmt.Println(answer)
}
